 function stopAll(list){list.forEach(a=>{try{a.pause();a.currentTime=0}catch{}});}
 function update(msg=''){if(!live())return;button.disabled=special.disabled=busy||!state.admin;button.textContent='Тест прокрутки';note.textContent=msg||'Админ-тест: без наград и изменения баланса.';}
