 const observer=new MutationObserver(()=>{if(!live())stop();});observer.observe($('modal'),{attributes:true,attributeFilter:['class']});observer.observe($('content'),{childList:true});document.addEventListener('visibilitychange',visibility);$('marketWheelBack').onclick=()=>{stop();openAdmin();};update();startTheme();
