 function finish(){if(!live())return;angle=target%360;pointer.style.transform=`rotate(${angle}deg)`;if(anim){anim.cancel();anim=null;}bells.pause();if(amount!==null){busy=false;update('Тест завершён · баланс не изменён');startTheme();}else{theme.pause();royalSetVolume(theme,true);note.textContent='Предпросмотр коронации';}}
