window.openAdminWheelTest=(i)=>{if(!state.admin)return;if(i===1)openMoggedPreview(marketWheelArts[1]);else if(i===2)openRoyalPreview(marketWheelArts[2]);};
function openMarketWheelGallery(){const counts=[sheriffLevelAvailable(),moggedLevelAvailable(),royalLevelAvailable()],levels=[10,30,60];show(`<div class="market-wheel-heading"><button type="button" class="market-wheel-back" id="marketWheelBack" aria-label="Назад">←</button><h2>Рулетки</h2></div><div class="market-wheel-grid">${marketWheelArts.map((w,i)=>{const available=counts[i]>0||state.admin&&i>0;return `<button type="button" class="market-wheel-card ${available?'':'locked'}" data-level-wheel="${i}" ${available?'':'disabled'}>${available||wheelUnlocked(i)?`<img src="${w.art}" alt="${w.title}"><span class="wheel-open-label">Наград: ${fmt(counts[i])}</span>`:`<div class="wheel-mystery">?</div><span class="wheel-lock">🔒 ${i===2?'Заверши цикл':'Уровень '+levels[i]}</span>`}</button>`;}).join('')}</div><p>Бесплатные награды за уровни, циклы и время. Королевская — за завершение цикла.</p>`);$('marketWheelBack').onclick=market;document.querySelectorAll('[data-level-wheel]').forEach(btn=>btn.onclick=()=>openMarketWheelPreview(Number(btn.dataset.levelWheel)));}
function openMarketWheelPreview(i){if(i===0&&sheriffLevelAvailable()>0)openSheriffPreview(marketWheelArts[0]);else if(i===1&&moggedLevelAvailable()>0)openMoggedPreviewEarned(marketWheelArts[1]);else if(i===2&&royalLevelAvailable()>0)openRoyalPreviewEarned(marketWheelArts[2]);else if(state.admin&&i>0)openAdmin();}
function openSheriffPreview(w){
 const full='data:image/webp;base64,';
 const theme=new Audio('data:audio/mpeg;base64,'), entrance=new Audio('data:audio/mpeg;base64,'), shout=new Audio('data:audio/mpeg;base64,');
 theme.loop=true;
 show(`<div class="sheriff-preview"><div class="market-wheel-heading"><button type="button" class="market-wheel-back" id="marketWheelBack" aria-label="Назад">←</button><h2>Рулетка шерифа</h2></div><div class="sheriff-scene" id="sheriffScene"><img src="${w.art}" alt="Шериф и колесо"><img class="sheriff-prizes" src="${full}" alt="Иллюстрация призов"><span class="sheriff-fixed-prize" aria-label="300 000">300 000</span><div class="sheriff-orbit" aria-hidden="true"><svg id="sheriffPointer" viewBox="0 0 400 400"><path d="M190 15 Q190 12 194 12 H206 Q210 12 210 15 V29 H220 Q224 29 222 34 L203 60 Q200 64 197 60 L178 34 Q176 29 180 29 H190 Z" fill="#ffdf27" stroke="#fff2a3" stroke-width="1.5" stroke-linejoin="round"/></svg></div></div><button type="button" class="sheriff-demo-btn" id="sheriffDemo" disabled>Открыть бесплатную награду уровня</button><p class="sheriff-note" id="sheriffNote" role="status">Открывается оформление…</p></div>`);
 const scene=$('sheriffScene'),button=$('sheriffDemo'),note=$('sheriffNote'),pointer=$('sheriffPointer');
 let stopped=false,animation=null,angle=0;
 const live=()=>!stopped&&scene.isConnected&&$('modal').classList.contains('show');
 function syncAudio(){theme.volume=state.muted?0:state.musicVolume/100;entrance.volume=shout.volume=state.muted?0:state.volume/100;}
 function play(a){try{const result=a.play();if(result)result.catch(()=>{});}catch{}}
 function stop(){if(stopped)return;stopped=true;[theme,entrance,shout].forEach(a=>{a.pause();try{a.currentTime=0}catch{}});if(animation)animation.cancel();observer.disconnect();document.removeEventListener('visibilitychange',visibility);clearTimeout(revealTimer);clearTimeout(readyTimer);}
 function visibility(){if(!live())return;if(document.hidden){[theme,entrance,shout].forEach(a=>a.pause());}else{syncAudio();play(theme);}}
 const observer=new MutationObserver(()=>{if(!live())stop();});observer.observe($('modal'),{attributes:true,attributeFilter:['class']});observer.observe($('content'),{childList:true});
 document.addEventListener('visibilitychange',visibility);
 $('marketWheelBack').onclick=()=>{stop();openMarketWheelGallery()};
 syncAudio();play(theme);play(entrance);
 const revealTimer=setTimeout(()=>{if(live())scene.classList.add('revealed');},120);
 function updateSheriffReward(message=''){const count=sheriffLevelAvailable();button.disabled=count<1;button.textContent=adminGuaranteeActive()?'Получить главный приз · гарант 100%':'Открыть бесплатную награду уровня';note.textContent=(message?message+' · ':'')+(count?'Доступно наград уровня: '+fmt(count)+' · Бесплатно за уровень':'Награда уровня уже получена. Следующая — в новом цикле.');}
 const readyTimer=setTimeout(()=>{if(live())updateSheriffReward();},1300);
 button.onclick=()=>{
  if(button.disabled||!live()||sheriffLevelAvailable()<1)return;
  // One positive, free achievement reward. No balance is spent.
  const rewards=[1000000,200000,150000,75000,50000,25000,10000,300000];
  const sector=adminGuaranteeActive()?0:Math.floor(Math.random()*rewards.length),reward=rewards[sector];
  if(state.sheriffEarned>state.sheriffLevelClaims)state.sheriffLevelClaims++;else state.sheriffBonusSpins--;gainGold(reward);save();render();
  syncAudio();if(theme.paused&&!document.hidden)play(theme);try{shout.currentTime=0}catch{}play(shout);
  button.disabled=true;note.textContent='Открывается награда уровня…';
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
  const sectorAngle=sector*45;
  const normalized=((sectorAngle-angle)%360+360)%360;
  const fullTurns=4+Math.floor(Math.random()*3);
  const target=angle+fullTurns*360+normalized;
  const duration=reduced?0:rewardDuration(4200);
  animation=pointer.animate([
   {transform:`rotate(${angle}deg)`},
   {transform:`rotate(${angle+18}deg)`,offset:.04},
   {transform:`rotate(${target}deg)`}
  ],{duration,easing:'cubic-bezier(.08,.78,.16,1)',fill:'forwards'});
  animation.onfinish=()=>{if(!live())return;angle=target%360;pointer.style.transform=`rotate(${angle}deg)`;animation.cancel();animation=null;updateSheriffReward('Получено +'+fmt(reward)+' · Баланс: '+fmt(state.gold));if(reward===1000000)celebrateSheriffMillion();};
 };
}


