function syavaGrant(item){const first=item.id==='horror'&&!state.owned[2];const amount=first?0:syavaAmounts[item.id];state.syavaCollection={...state.syavaCollection,[item.id]:true};if(first)state.owned[2]=true;gainGold(amount);save();render();return first?'Открыт персонаж: '+item.name:'Получено +'+fmt(amount)+' ацетончиков';}

