 el.innerHTML=`<div class="gz-nebula"></div><div class="gz-halo"></div><div class="gz-floor"></div><canvas></canvas><div class="gz-result"><small>${preview?'ПРЕДПРОСМОТР':'МИФИЧЕСКИЙ ОБЛИК'}</small><h2>${item.name}</h2><div class="gz-hero"><img src="${item.image}" alt="${item.name}"></div><button>Продолжить</button></div><button class="gz-skip">Пропустить анимацию</button>`;document.body.append(el);document.body.classList.add('gz-fx-active');
