 function done(){if(closed)return;closed=true;cancelAnimationFrame(raf);cue.close();window.removeEventListener('resize',resize);document.removeEventListener('visibilitychange',visibility);el.remove();document.body.classList.remove('gz-fx-active');render();onDone?.();}
