 function reveal(){if(revealed)return;revealed=true;cue.seekReveal();el.classList.add('revealed');}
 document.addEventListener('visibilitychange',visibility);el.querySelector('.gz-result button').onclick=done;el.querySelector('.gz-skip').onclick=()=>{start=performance.now()-2700;reveal();};
 const flameSprite=document.createElement('canvas');flameSprite.width=192;flameSprite.height=192;const fc=flameSprite.getContext('2d');
 if(fc){const g=fc.createRadialGradient(96,96,0,96,96,86);g.addColorStop(0,'rgba(185,248,255,.82)');g.addColorStop(.18,'rgba(36,187,255,.83)');g.addColorStop(.46,'rgba(0,82,255,.6)');g.addColorStop(.76,'rgba(19,33,190,.23)');g.addColorStop(1,'rgba(0,22,155,0)');fc.fillStyle=g;fc.fillRect(0,0,192,192);fc.translate(96,96);fc.rotate(-.63);fc.fillStyle='rgba(58,181,255,.28)';fc.beginPath();fc.moveTo(-31,38);fc.bezierCurveTo(-74,-11,15,-32,-15,-93);fc.bezierCurveTo(53,-46,47,14,22,42);fc.closePath();fc.fill();}
 function flame(x,y,r,alpha,t,seed){if(!fc||alpha<=0||x+r*1.2<0||x-r*1.2>W||y+r*1.2<0||y-r*1.2>H)return;ctx.globalAlpha=Math.max(0,Math.min(1,alpha));const size=r*2.23;ctx.drawImage(flameSprite,x-size/2,y-size/2,size,size);ctx.globalAlpha=1;}
 let lastFrame=-Infinity;
