 if(t<2.65){const u=Math.min(1,t/2.05),lead=1.55-2.15*u,fade=t>2.05?Math.max(0,1-(t-2.05)/.60):1;for(let layer=0;layer<3;layer++){for(let i=0;i<18;i++){const f=i/17,delta=layer*.13,xx=W*(lead+f*.72+delta)+Math.sin(f*17+t*9+layer)*unit*.055,yy=H*(lead+(1-f)*.56+delta)+Math.cos(f*19+t*7+layer)*unit*.08;const rad=unit*(.11+.055*Math.sin(i*2.4+t*8+layer)+layer*.018);flame(xx,yy,rad,fade*(.68-layer*.12),t,i+layer*4);}}}
