 // Ambient flames stay near the edges after the character is revealed.
 if(revealed){for(let i=0;i<16;i++){const side=i%2,phase=(t*.43+i*.179)%1,y=H*(1.06-phase*.89),x=W*(side?.92:.08)+Math.sin(t*3+i*1.9)*unit*.075;flame(x,y,unit*(.05+.045*(1-phase)),(1-phase)*.42,t,i);}}
 for(const p of motes){const q=(p.y+t*p.v)%1.15,x=W*(p.x+.045*Math.sin(t*1.7+p.y*17)),y=H*(1.08-q);ctx.fillStyle=`rgba(101,217,255,${.15+.5*Math.sin(Math.PI*Math.min(1,q))})`;ctx.beginPath();ctx.arc(x,y,p.s,0,Math.PI*2);ctx.fill();}
