function bullCount(){return `<div class="case-keys" id="bullKeyInline">${syavaKeyIcon}<b>Ключей: ${fmt(state.bullKeys)}</b></div>`;}
function bullTile(i,chance=false){return syavaItemCard(i,i.id==='bychok'?'bull-legend':'',chance,false);}
function bullGuaranteed(){const v=state.admin&&adminCaseRarity.bull;return v?bullItems.find(i=>i.name===v||i.rarity===v)||null:null;}
function bullReveal(text,onClose){const el=document.createElement('div');el.className='bull-reveal';const sparks=Array.from({length:26},(_,i)=>`<i class="bull-spark" style="--x:${(i*29)%100}%;--y:${46+(i*13)%28}%;--d:${(i%7)*.23}s"></i>`).join('');el.innerHTML=`<div class="bull-flare"></div>${sparks}<section><small>ЛЕГЕНДАРНАЯ НАГРАДА</small><img src="${sonBaseImage}" alt="Бычок"><h2>БЫЧОК</h2><p>${text}</p><button class="syava-action">Забрать</button></section>`;document.body.append(el);const close=()=>{el.remove();onClose?.();};el.querySelector('button').onclick=close;el.onclick=e=>{if(e.target===el)close();};if(!state.muted)winSound(50000);}
