 const finish=()=>{sound.play('stop');busy=false;const visible=strip.isConnected&&$('modal').classList.contains('show');if(visible){openBullCase(result.id,msg);if(result.id==='bychok')bullReveal(msg,()=>sound.close(0));else sound.close();}else sound.close();};
