{id:'bull',name:'Бычкоджон',rarity:'Мифическая',chance:24,color:'#ff526d',image:bychkodjonImage,key:'bychkodjonOwned',cue:4.5},
{id:'hero',name:'Кочстянчик',rarity:'Легендарная',chance:1,color:'#ffcf61',image:legendImageFixed,key:'legendOwned',cue:2.5},
{id:'vorsin',name:'Ворсин',rarity:'Легендарная',chance:5,color:'#ffcf61',image:vorsinImage,cue:3}
