function openSyavaCase(lastId,message=''){
 const display=syavaItems.find(i=>i.id===lastId)||syavaItems[0];
 show(`<div class="syava-ui">${syavaHeading('Кейс Сява')}<img class="syava-cover" src="${syavaArt}" alt="Кейс Сява"><div class="syava-focus" id="syavaFocus"><div class="syava-strip" id="syavaStrip">${[syavaItems[3],syavaItems[4],display,syavaItems[1],syavaItems[2]].map(i=>syavaItemCard(i)).join('')}</div><div class="syava-ring"></div><div class="syava-marker"></div></div><p id="syavaStatus" role="status">${message||(adminCaseChoice('syava',syavaItems)?'Админ-гарант: '+adminCaseRarity.syava:'Ключи выдаются только за уровни «Пути Сявы».')}</p><button id="syavaUse" class="syava-action" ${state.syavaKeys<1?'disabled':''}>Открыть кейс</button>${syavaCount()}<button id="syavaPath" class="syava-back">Путь Сявы · уровни 1–10</button><h3>Содержимое кейса</h3><div class="syava-grid">${syavaItems.map(i=>syavaItemCard(i,'',true)).join('')}</div><h3>Коллекция</h3><div class="syava-collection">${syavaItems.filter(i=>state.syavaCollection[i.id]||(i.id==='horror'&&state.owned[2])).map(i=>'<span>✓ '+i.name+'</span>').join('')||'<span>Пока пусто</span>'}</div></div>`);
 const strip=$('syavaStrip'),focus=$('syavaFocus'),status=$('syavaStatus'),button=$('syavaUse');let busy=false;
 const center=index=>focus.clientWidth/2-strip.children[index].offsetLeft-strip.children[index].offsetWidth/2;
 function place(x){strip.style.transform=`translateX(${x}px)`;const c=focus.clientWidth/2-x;for(const node of strip.children){const dist=Math.abs(node.offsetLeft+node.offsetWidth/2-c);node.style.filter=`blur(${Math.min(5,Math.max(0,(dist-70)/19))}px)`;node.style.opacity=String(Math.max(.58,1-Math.max(0,dist-72)/320));}}
 place(center(2));$('syavaBack').onclick=openSyavaGallery;$('syavaPath').onclick=()=>openLevels();
 button.onclick=()=>{if(busy||state.syavaKeys<1)return;busy=true;button.disabled=true;const sound=syavaAudio();const result=syavaPickRandom();const finalIndex=34,items=Array.from({length:39},()=>syavaItems[Math.floor(Math.random()*syavaItems.length)]);items[finalIndex]=result;
 // A key is a non-purchasable, non-transferable claim ticket for an earned level reward.
 const hiddenHorror=!state.owned[2],newHorror=result.id==='horror'&&hiddenHorror;state.syavaKeys--;const finalMessage=syavaGrant(result);const counter=document.querySelector('#syavaKeyInline b');if(counter)counter.textContent='Ключей: '+fmt(state.syavaKeys);status.textContent='Получение награды…';
 strip.innerHTML=items.map(i=>syavaItemCard(i,'',false,i.id==='horror'&&hiddenHorror)).join('');const from=center(2),to=center(finalIndex),stride=strip.children[1].offsetLeft-strip.children[0].offsetLeft;place(from);sound.play('open');
 let last=2;const duration=rewardDuration(5000),start=performance.now();const finish=()=>{sound.play('stop');sound.close();busy=false;if(strip.isConnected&&$('modal').classList.contains('show')){openSyavaCase(result.id,finalMessage);if(result.id==='horror')revealHorror(newHorror);}};
 if(matchMedia('(prefers-reduced-motion: reduce)').matches){finish();return;}
 function tick(now){if(!strip.isConnected||!$('modal').classList.contains('show')){sound.close();return;}const t=Math.min(1,(now-start)/duration),ease=1-Math.pow(1-t,3);place(from+(to-from)*ease);const index=Math.round(2+(finalIndex-2)*ease);if(index!==last){sound.play('tick');last=index;}if(t<1)requestAnimationFrame(tick);else finish();}requestAnimationFrame(tick);
 };
}
