function forestReveal(text,onClose){const el=document.createElement('div');el.className='forest-reveal';const paths=['M-12 790 Q98 735 67 610 T140 436 T100 250 T170 80','M-15 650 Q120 550 105 450 T220 300','M-10 910 Q180 850 220 715 T270 520','M412 790 Q302 735 333 610 T260 436 T300 250 T230 80','M415 650 Q280 550 295 450 T180 300','M410 910 Q220 850 180 715 T130 520','M30 -20 Q12 120 90 180 T125 310','M370 -20 Q388 120 310 180 T275 310'];const vines=paths.map((d,i)=>`<g style="--d:${i*.14}s"><path class="root" pathLength="1" d="${d}"/><path class="vine" pathLength="1" d="${d}"/></g>`).join('');const leaves=Array.from({length:28},(_,i)=>{const x=i%2?35+(i*19)%105:365-(i*19)%105,y=100+(i*53)%690;return `<path class="leaf" style="--d:${1.1+i*.045}s" d="M${x} ${y}q-19 -25 -26 -3q10 21 26 3Z"/>`;}).join('');const sparks=Array.from({length:30},(_,i)=>`<i class="forest-spark" style="--x:${(i*37)%100}%;--y:${(i*23)%78}%;--d:${2+i*.11}s"></i>`).join('');el.innerHTML=`<svg class="forest-cinema" viewBox="0 0 400 900" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><path class="trail" d="M155 450L245 450 360 900 40 900Z"/>${vines}${leaves}</svg><div class="forest-halo"></div>${sparks}<section><div class="forest-caption"><small>ЛЕГЕНДАРНЫЙ ОБЛИК</small><h2>Изумрудный король</h2></div><div class="king-walk"><img src="${horrorRoyalImage}" alt="Изумрудный король"></div><div class="forest-footer"><p>${text}</p><button>Продолжить</button></div></section>`;document.body.append(el);el.querySelector('button').onclick=()=>{el.remove();if(onClose)onClose();};}
